//! Which of an offer's MIME types to read, and which offers never to read at all. Pure.
//!
//! Password managers mark what they copy so clipboard managers leave it alone: KDE's
//! `x-kde-passwordManagerHint` (value `secret`; KeePassXC, KWallet, Plasma's own), and the
//! nspasteboard.org types (`org.nspasteboard.ConcealedType`, `...TransientType`,
//! `...AutoGeneratedType`) some cross-platform managers also set on Linux. An offer carrying any
//! of [`SECRET_HINTS`] is skipped **before any of it is read**: its presence is enough, so the
//! service never receives the secret's bytes.

/// MIME types whose presence marks an offer as not for history.
pub const SECRET_HINTS: &[&str] = &[
    "x-kde-passwordManagerHint",
    "application/x-kde-passwordManagerHint",
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
];

/// What to do with an offer.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum OfferVerdict {
    /// Read this type.
    Read(MimePick),
    /// A password manager's: read nothing.
    Secret,
    /// Nothing the service keeps (only private or unknown types).
    Nothing,
}

/// The type chosen.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum MimePick {
    /// `text/plain;charset=utf-8`, else `text/plain`, `UTF8_STRING`, `STRING`, `TEXT`.
    Text(String),
    /// `image/png`, else another `image/*` the `image` crate decodes (JPEG).
    Image(String),
}

/// The verdict on an offer of `mimes` (in the order the source offered them). Text wins over an
/// image when both are offered (a browser copying a picture offers its URL as text too; macOS
/// keeps the richer one, but the launcher's row and paste are text first). `images` is
/// whether the policy keeps images at all.
pub fn offer_verdict(mimes: &[String], images: ImagesKept) -> OfferVerdict {
    if mimes
        .iter()
        .any(|mime| SECRET_HINTS.contains(&mime.as_str()))
    {
        return OfferVerdict::Secret;
    }
    let text = best_of(mimes, TEXT_TYPES).map(MimePick::Text);
    let image = match images {
        ImagesKept::Kept => best_of(mimes, IMAGE_TYPES).map(MimePick::Image),
        ImagesKept::Skipped => None,
    };
    text.or(image)
        .map_or(OfferVerdict::Nothing, OfferVerdict::Read)
}

/// The text types read, preferred first. `STRING` and `TEXT` are X11's Latin-1 forms; what
/// they hold is kept only when it is valid UTF-8 (ASCII always is).
const TEXT_TYPES: &[&str] = &[
    "text/plain;charset=utf-8",
    "text/plain",
    "UTF8_STRING",
    "STRING",
    "TEXT",
];

/// The image types read, preferred first: the ones the workspace's `image` build decodes.
const IMAGE_TYPES: &[&str] = &["image/png", "image/jpeg", "image/jpg"];

/// The offered type (as the source spelled it) that comes first in `preferred`, compared
/// without regard to case (`text/plain;charset=UTF-8` is the same type).
fn best_of(mimes: &[String], preferred: &[&str]) -> Option<String> {
    preferred.iter().find_map(|want| {
        mimes
            .iter()
            .find(|offered| offered.eq_ignore_ascii_case(want))
            .cloned()
    })
}

/// Whether images are kept (the policy's image cap is not zero).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum ImagesKept {
    Kept,
    Skipped,
}

#[cfg(test)]
mod tests {
    use super::{ImagesKept, MimePick, OfferVerdict, offer_verdict};

    fn mimes(list: &[&str]) -> Vec<String> {
        list.iter().map(|m| (*m).to_owned()).collect()
    }

    #[test]
    fn secrets_are_never_read_and_text_is_preferred() {
        let cases: Vec<(&[&str], ImagesKept, OfferVerdict)> = vec![
            (
                &["text/plain", "x-kde-passwordManagerHint"],
                ImagesKept::Kept,
                OfferVerdict::Secret,
            ),
            (
                &["UTF8_STRING", "org.nspasteboard.ConcealedType"],
                ImagesKept::Kept,
                OfferVerdict::Secret,
            ),
            (
                &["STRING", "text/plain", "text/plain;charset=utf-8"],
                ImagesKept::Kept,
                OfferVerdict::Read(MimePick::Text("text/plain;charset=utf-8".to_owned())),
            ),
            (
                &["UTF8_STRING"],
                ImagesKept::Kept,
                OfferVerdict::Read(MimePick::Text("UTF8_STRING".to_owned())),
            ),
            (
                &["image/jpeg", "image/png"],
                ImagesKept::Kept,
                OfferVerdict::Read(MimePick::Image("image/png".to_owned())),
            ),
            (
                &["text/uri-list", "text/plain", "image/png"],
                ImagesKept::Kept,
                OfferVerdict::Read(MimePick::Text("text/plain".to_owned())),
            ),
            (&["image/png"], ImagesKept::Skipped, OfferVerdict::Nothing),
            (
                &["application/x-private-thing", "SAVE_TARGETS"],
                ImagesKept::Kept,
                OfferVerdict::Nothing,
            ),
            (&[], ImagesKept::Kept, OfferVerdict::Nothing),
        ];
        for (offer, images, want) in cases {
            assert_eq!(offer_verdict(&mimes(offer), images), want, "{offer:?}");
        }
    }

    #[test]
    fn a_hint_alone_or_a_spelling_still_decides() {
        let cases: Vec<(&[&str], ImagesKept, OfferVerdict)> = vec![
            (
                &["application/x-kde-passwordManagerHint", "image/png"],
                ImagesKept::Kept,
                OfferVerdict::Secret,
            ),
            (
                &["org.nspasteboard.TransientType"],
                ImagesKept::Skipped,
                OfferVerdict::Secret,
            ),
            (
                &["text/plain;charset=UTF-8"],
                ImagesKept::Kept,
                OfferVerdict::Read(MimePick::Text("text/plain;charset=UTF-8".to_owned())),
            ),
            (
                &["image/jpeg", "image/bmp"],
                ImagesKept::Kept,
                OfferVerdict::Read(MimePick::Image("image/jpeg".to_owned())),
            ),
            (
                &["image/png", "TEXT"],
                ImagesKept::Skipped,
                OfferVerdict::Read(MimePick::Text("TEXT".to_owned())),
            ),
            (
                &["image/bmp", "text/html"],
                ImagesKept::Kept,
                OfferVerdict::Nothing,
            ),
        ];
        for (offer, images, want) in cases {
            assert_eq!(offer_verdict(&mimes(offer), images), want, "{offer:?}");
        }
    }
}
